// The engine's own lines this mod rewrites or redraws while it is loaded, and the band above
// the prompt it adds to. Each hook counts its call and keeps the props it received first (so
// the pane can tell "not raised" from "raised but not drawn", and list what came in), then
// passes `next(e)` on unchanged when its site is switched off in the pane.

import { DIALOG_OPEN, noteCall, noteProps, formatValue, toggleValue } from './sites.js'
import { SPACE, BUTTON, dim, inline } from './style.js'
import { noteInvalidate } from './diag.js'
import { redrawFor } from './redraw.js'
import { atom, read, update } from 'claude-code'

// The state this file reads (declared in types/index.d.ts): one switch per site id, which
// prop [PromptHint], [Spinner] and [CommandOutput] write, and the band's and [DialogPane]'s echo
// lines
const TOGGLES = { plugin: 'ui-sampler', key: 'toggles' }
const ECHO = { plugin: 'ui-sampler', key: 'echo' }
const promptHintMode = atom({ plugin: 'ui-sampler', key: 'promptHintMode' }, 'hint')
const spinnerMode = atom({ plugin: 'ui-sampler', key: 'spinnerMode' }, 'word')
const commandOutputMode = atom({ plugin: 'ui-sampler', key: 'commandOutputMode' }, 'tree')

// Counts the call and keeps the props; redraws the pane only when it shows what changed
// (redraw.js). The Spinner's props can change many times in a turn, so its
// redraws are marked as noise for the diag log.
function noteRender($, id, e) {
  const isNew = noteCall(id, e.surface)
  const isChanged = noteProps(id, e)
  const why = redrawFor(id, { isNew, isChanged }, Date.now())
  if (!why) return
  noteInvalidate(`${id} の${why === 'first' ? '初回描画' : ' props が変わった'}`, id === 'Spinner')
  $.ui.invalidate('ui.render')
}

// Reading the switch while drawing subscribes the hook, so a press in the pane redraws it
async function isOn($, id) {
  return toggleValue(id, await read($, { ...TOGGLES, id }))
}

// Writes one of the band's echo lines from a handler (never while drawing)
function echoTo($, id, text) {
  return update($, { ...ECHO, id }, () => text)
}

// Reading an echo while drawing subscribes the band, so a write redraws it
async function echoOf($, id) {
  return (await read($, { ...ECHO, id })) ?? 'まだ何もしていない'
}

// ===== [DialogPane] $.ui.open({ id: 'ui-sampler-dialog', ... }) from the band =====
// One of three entry points (also the main pane's dialogs view button and /ui-sampler-dialog), all with
// DIALOG_OPEN. The opener is written before the open so the pane's first drawing shows it.
async function openDialogFromBand($, press) {
  await echoTo($, 'DialogPane:openedBy', `[AbovePrompt] の帯のボタン（ui.press、surface: ${press.surface}）`)
  const opened = await $.ui.open(DIALOG_OPEN)
  const result = opened.isPlaced ? 'isPlaced: true' : `isPlaced: false、reason: ${opened.reason}`
  await echoTo($, 'DialogPane:openResult', result)
  return echoTo($, 'AbovePrompt:press', `[DialogPane] を開いた（${result}）`)
}

// `name=value` for every prop received, in the order they came
const propPairs = props =>
  Object.entries(props)
    .map(([name, value]) => `${name}=${formatValue(value)}`)
    .join(' ')

export function registerEngineLines(on) {
  // ===== [Spinner] ui.render { component: 'Spinner' } =====
  // The line that animates while a turn runs. The pane chooses what to write: `word`,
  // `message` or `suffix`; a tree of its own that lists the props received; or that list
  // written into `word`.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    noteRender($, 'Spinner', e)
    if (!(await isOn($, 'Spinner'))) return next(e)
    const mode = await read($, spinnerMode)
    switch (mode) {
      case 'message':
        return next({ ...e, props: { ...e.props, message: '[Spinner] message を書き換え' } })
      case 'suffix':
        return next({ ...e, props: { ...e.props, suffix: ' [Spinner] suffix を書き換え' } })
      case 'tree': {
        const { Text } = $.ui.resolve(e)
        return Text({
          color: 'warning',
          wrap: 'wrap',
          children: ['[Spinner] 自前のツリー: ' + propPairs(e.props)],
        })
      }
      case 'props':
        return next({ ...e, props: { ...e.props, word: '[Spinner] ' + propPairs(e.props) } })
      default:
        return next({ ...e, props: { ...e.props, word: '[Spinner] word を書き換え' } })
    }
  })

  // ===== [SessionMode] ui.render { component: 'SessionMode' } =====
  // The mode labels in the prompt footer. A tree of our own in their place, which still
  // shows the labels the engine handed over.
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    noteRender($, 'SessionMode', e)
    if (!(await isOn($, 'SessionMode'))) return next(e)
    const { Text } = $.ui.resolve(e)
    const original = e.props.modes.length > 0 ? e.props.modes.join(' & ') : 'なし'
    return Text({ color: 'warning', children: [`[SessionMode] モード表示を描き替え（元: ${original}）`] })
  })

  // ===== [PromptHint] ui.render { component: 'PromptHint' } =====
  // The dim hint line under the prompt. The pane chooses which prop to write:
  // `hint` replaces the whole line, `tail` adds text after the engine's own line.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    noteRender($, 'PromptHint', e)
    if (!(await isOn($, 'PromptHint'))) return next(e)
    const mode = await read($, promptHintMode)
    if (mode === 'tail') {
      return next({ ...e, props: { ...e.props, tail: '[PromptHint] tail に足した文字' } })
    }
    return next({ ...e, props: { ...e.props, hint: `[PromptHint] hint を書き換え（元: ${e.props.hint}）` } })
  })

  // ===== [AbovePrompt] ui.render { component: 'AbovePrompt' } =====
  // The band above the prompt. Other mods draw here too, so this asks `next(e)` for theirs
  // first and puts its own labelled row above it rather than replacing it; while a survey
  // holds the band it passes.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    noteRender($, 'AbovePrompt', e)
    const inner = await next(e)
    if (e.props.hasSurvey || !(await isOn($, 'AbovePrompt'))) return inner
    const ui = $.ui.resolve(e)
    const { Box, Text, Button, Input } = ui
    // One row: the label, the two buttons, the input, then the echoes cut to what is left of
    // the width; it wraps only when the band is too narrow for the controls
    const ours = Box({
      paddingX: SPACE.page,
      flexDirection: 'row',
      columnGap: SPACE.column,
      rowGap: SPACE.control,
      alignItems: 'center',
      flexWrap: 'wrap',
      width: '100%',
      children: [
        Text({ bold: true, children: ['[AbovePrompt]'] }),
        inline(ui, 'band-buttons', [
          Button({
            key: 'band-press',
            label: '帯のボタン',
            ...BUTTON.nav,
            onPress: press => echoTo($, 'AbovePrompt:press', `押された（e.surface: ${press.surface}）`),
          }),
          Button({
            key: 'band-dialog',
            label: '[DialogPane] を開く',
            ...BUTTON.nav,
            onPress: press => openDialogFromBand($, press),
          }),
        ]),
        Input({
          key: 'band-input',
          label: '帯の入力',
          placeholder: 'ここに入力して Enter',
          submitLabel: '写す',
          onSubmit: value => echoTo($, 'AbovePrompt:submit', value),
        }),
        Box({
          flexGrow: 1,
          flexShrink: 1,
          children: [
            Text({
              dimColor: true,
              wrap: 'truncate-end',
              children: [`ボタン: ${await echoOf($, 'AbovePrompt:press')} / 入力: ${await echoOf($, 'AbovePrompt:submit')}`],
            }),
          ],
        }),
      ],
    })
    if (!inner) return ours
    return Box({
      flexDirection: 'column',
      children: [ours, dim(ui, 'band-others', '[AbovePrompt] この下はほかの mod の帯（next(e) が返したもの）'), inner],
    })
  })

  // ===== [CommandOutput] ui.render { component: 'CommandOutput', props: { command: 'ui-sampler' } } =====
  // The row /ui-sampler leaves in the transcript. command.run answered text starting with
  // [command.run]. The pane chooses: a tree that puts [CommandOutput] in front of that text,
  // or a rewrite of `text` the engine draws in its own row. Switched off, the engine draws
  // the plain [command.run] text alone.
  // The matcher is COMMAND's value as a literal, so `plugin validate` can list it
  on('ui.render', { component: 'CommandOutput', props: { command: 'ui-sampler' } }, async ($, e, next) => {
    noteRender($, 'CommandOutput', e)
    if (!(await isOn($, 'CommandOutput'))) return next(e)
    const mode = await read($, commandOutputMode)
    if (mode === 'text') {
      return next({ ...e, props: { ...e.props, text: `[CommandOutput] text を書き換え（元: ${e.props.text}）` } })
    }
    const { Box, Text } = $.ui.resolve(e)
    return Box({
      flexDirection: 'row',
      columnGap: 1,
      children: [
        Text({ color: 'success', bold: true, children: ['[CommandOutput] 自前のツリー'] }),
        Text({ wrap: 'wrap', children: [e.props.text] }),
      ],
    })
  })
}

files.hooks/transcript.js:
// The transcript's rows: the person's and Claude's messages, tool calls, their results and the
// folded runs of calls, plus the lines the type declarations say only the terminal raises.
// A row site switched on keeps the engine's row (what `next(e)` returns) and puts one labelled
// line above it; switched off it passes `next(e)` on unchanged. The terminal-only sites only
// count their calls and keep their props.
//
// Many rows share one site, so these hooks redraw (the pane's counts) only when a site or a
// surface is new and the pane lists it, never because the props changed: with several rows
// each would take its turn as "changed", and every redraw draws every row again.

import { noteCall, keepProps, toggleValue } from './sites.js'
import { noteInvalidate } from './diag.js'
import { redrawFor } from './redraw.js'
import { read } from 'claude-code'

// The state this file reads (declared in types/index.d.ts): one switch per site id
const TOGGLES = { plugin: 'ui-sampler', key: 'toggles' }

// Counts the call and keeps the props; redraws once when the site or the surface is new and
// the pane lists the site (redraw.js)
function noteRow($, id, e) {
  keepProps(id, e)
  const isNew = noteCall(id, e.surface)
  if (!redrawFor(id, { isNew }, Date.now())) return
  noteInvalidate(`${id} の初回描画`)
  $.ui.invalidate('ui.render')
}

// Reading the switch while drawing subscribes the row, so a press in the pane redraws it
async function isOn($, id) {
  return toggleValue(id, await read($, { ...TOGGLES, id }))
}

// The engine's row with the labelled lines above it
function labelled($, e, inner, lines) {
  const { Box, Text } = $.ui.resolve(e)
  return Box({
    flexDirection: 'column',
    children: [
      ...lines.map((text, index) => Text({ key: 'label' + index, color: 'warning', wrap: 'wrap', children: [text] })),
      inner,
    ],
  })
}

/** A tool call's name list for a label: `Read, Read, Bash`, cut after a few. */
function toolNames(calls) {
  const names = calls.slice(0, 5).map(call => call.tool)
  return names.join(', ') + (calls.length > 5 ? ` ほか ${calls.length - 5} 件` : '')
}

export function registerTranscript(on) {
  // ===== [UserMessage] ui.render { component: 'UserMessage' } =====
  // The person's prompt, a background task's notification, a message another agent or session
  // sent. The label says which, by origin.kind.
  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    noteRow($, 'UserMessage', e)
    if (!(await isOn($, 'UserMessage'))) return next(e)
    const inner = await next(e)
    const { origin, isExpanded } = e.props
    return labelled($, e, inner, [
      `[UserMessage] ui-sampler が足した行（origin.kind: ${origin?.kind ?? '（なし）'}、isExpanded: ${isExpanded}）`,
    ])
  })

  // ===== [AssistantMessage] ui.render { component: 'AssistantMessage' } =====
  // One text block of a reply; a reply of several blocks gets a label above each
  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    noteRow($, 'AssistantMessage', e)
    if (!(await isOn($, 'AssistantMessage'))) return next(e)
    const inner = await next(e)
    return labelled($, e, inner, [
      `[AssistantMessage] ui-sampler が足した行（isFirstOfReply: ${e.props.isFirstOfReply}、${e.props.text.length} 文字）`,
    ])
  })

  // ===== [ToolUse] ui.render { component: 'ToolUse' } =====
  // A tool call's row; also each row an expanded [ToolGroup] unfolds into
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    noteRow($, 'ToolUse', e)
    if (!(await isOn($, 'ToolUse'))) return next(e)
    const inner = await next(e)
    const { tool, isRunning, isErrored, isInterrupted } = e.props
    return labelled($, e, inner, [
      `[ToolUse] ui-sampler が足した行（tool: ${tool}、isRunning: ${isRunning}、isErrored: ${isErrored}、isInterrupted: ${isInterrupted}）`,
    ])
  })

  // ===== [ToolResult] ui.render { component: 'ToolResult' } =====
  // The result block under a standalone tool row
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    noteRow($, 'ToolResult', e)
    if (!(await isOn($, 'ToolResult'))) return next(e)
    const inner = await next(e)
    return labelled($, e, inner, [
      `[ToolResult] ui-sampler が足した行（tool: ${e.props.tool}、isErrored: ${e.props.isErrored}）`,
    ])
  })

  // ===== [ToolGroup] [ToolGroup/isExpanded] ui.render { component: 'ToolGroup' } =====
  // The one-line count of a run of calls. Two switches: [ToolGroup] labels the row;
  // [ToolGroup/isExpanded] hands next(e) isExpanded: true, the one prop whose rewrite the
  // type declarations say changes the screen, so the run unfolds into [ToolUse] rows.
  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    noteRow($, 'ToolGroup', e)
    const isLabelOn = await isOn($, 'ToolGroup')
    const isExpandOn = await isOn($, 'ToolGroup/isExpanded')
    if (!isLabelOn && !isExpandOn) return next(e)
    if (isExpandOn) noteCall('ToolGroup/isExpanded', e.surface)
    const inner = await next(isExpandOn ? { ...e, props: { ...e.props, isExpanded: true } } : e)
    const { calls, isActive, isExpanded } = e.props
    const lines = []
    if (isLabelOn) {
      lines.push(
        `[ToolGroup] ui-sampler が足した行（calls: ${calls.length} 件 ${toolNames(calls)}、isActive: ${isActive}、isExpanded: ${isExpanded}）`,
      )
    }
    if (isExpandOn) lines.push(`[ToolGroup/isExpanded] isExpanded を true にして next(e) に渡した（元: ${isExpanded}）`)
    return labelled($, e, inner, lines)
  })

  // ===== [ToolProgress] ui.render { component: 'ToolProgress' } =====
  // Declared terminal-only: counted, props kept, drawn as the engine draws it
  on('ui.render', { component: 'ToolProgress' }, async ($, e, next) => {
    noteRow($, 'ToolProgress', e)
    return next(e)
  })

  // ===== [TurnDuration] ui.render { component: 'TurnDuration' } =====
  // Declared terminal-only: counted, props kept, drawn as the engine draws it
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    noteRow($, 'TurnDuration', e)
    return next(e)
  })

  // ===== [InfoNotice] ui.render { component: 'InfoNotice' } =====
  // Declared terminal-only: counted, props kept, drawn as the engine draws it
  on('ui.render', { component: 'InfoNotice' }, async ($, e, next) => {
    noteRow($, 'InfoNotice', e)
    return next(e)
  })
}

files.hooks/asks.js:
// The two dialogs that ask the person. The AskUserQuestion dialog is a render site:
// [AskUserQuestion] marks its question text and lets the engine draw it. The permission
// dialog is drawn by the engine alone (its answer authorises an action); a plugin only adds
// a line under it, which [$.ui.notice] does from a tool.call hook on Bash.

import { noteCall, noteProps, noteResult, toggleValue } from './sites.js'
import { noteInvalidate } from './diag.js'
import { redrawFor, paneLists } from './redraw.js'
import { read } from 'claude-code'

// The state this file reads (declared in types/index.d.ts): one switch per site id
const TOGGLES = { plugin: 'ui-sampler', key: 'toggles' }

// Counts the call and keeps the props; redraws the pane only when it shows what changed
// (redraw.js)
function noteRender($, id, e) {
  const isNew = noteCall(id, e.surface)
  const isChanged = noteProps(id, e)
  const why = redrawFor(id, { isNew, isChanged }, Date.now())
  if (!why) return
  noteInvalidate(`${id} の${why === 'first' ? '初回描画' : ' props が変わった'}`)
  $.ui.invalidate('ui.render')
}

// Redraws the pane for a new result line, when the pane lists the site
function redrawResult($, id) {
  if (!paneLists(id)) return
  noteInvalidate(`${id} の結果が変わった`)
  $.ui.invalidate('ui.render')
}

// Reading the switch while drawing subscribes the dialog, so a press in the pane redraws it
async function isOn($, id) {
  return toggleValue(id, await read($, { ...TOGGLES, id }))
}

/**
 * One entry of the tool's `questions` with its question text marked. The label goes on the
 * text, not on `header`: the tool's schema caps `header` at 12 characters, and a rewrite that
 * breaks the schema is drawn as the original.
 */
function markQuestion(question) {
  if (question === null || typeof question !== 'object' || typeof question.question !== 'string') return question
  return { ...question, question: '[AskUserQuestion] ' + question.question }
}

/** A command cut to one short line for the notice and the pane. */
function clip(command) {
  const line = String(command ?? '').replace(/\s+/g, ' ').trim()
  return line.length > 40 ? line.slice(0, 40) + '…' : line
}

export function registerAsks(on) {
  // ===== [AskUserQuestion] ui.render { component: 'AskUserQuestion' } =====
  // Raised both for Claude's AskUserQuestion calls and for $.ui.ask (the [$.ui.ask]
  // button in the main pane's dialogs view), which runs as a tool.call of AskUserQuestion
  on('ui.render', { component: 'AskUserQuestion' }, async ($, e, next) => {
    noteRender($, 'AskUserQuestion', e)
    if (!(await isOn($, 'AskUserQuestion'))) return next(e)
    const questions = Array.isArray(e.props.questions) ? e.props.questions.map(markQuestion) : e.props.questions
    return next({ ...e, props: { ...e.props, questions } })
  })

  // ===== [$.ui.notice] tool.call { tool: 'Bash' } → $.ui.notice(e.tool_use_id, text) =====
  // Called before next(e), as the type declarations' example does, so the line is in place
  // when the permission dialog below opens; the engine removes it when the call resolves.
  // A Bash call that needs no permission opens no dialog, and the line has nowhere to show.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (!(await isOn($, '$.ui.notice'))) return next(e)
    noteCall('$.ui.notice')
    const command = clip(e.command)
    let called
    try {
      $.ui.notice(e.tool_use_id, `[$.ui.notice] ui-sampler が許可ダイアログの下に足した行です（${command}）`)
      called = `呼んだ（tool_use_id: ${e.tool_use_id}、コマンド: ${command}）`
    } catch (error) {
      called = `エラー: ${String(error?.message ?? error)}（コマンド: ${command}）`
    }
    noteResult('$.ui.notice', called + '。実行を待っている')
    redrawResult($, '$.ui.notice')

    const ran = await next(e)
    const outcome =
      ran.deny !== undefined ? `断られた（deny: ${ran.deny}）` : ran.isError === true ? 'エラーで終わった' : '実行された'
    noteResult('$.ui.notice', `${called}。その後の呼び出し: ${outcome}`)
    redrawResult($, '$.ui.notice')
    return ran
  })
}

