// When a hook's new call or new props are worth redrawing the pane for.
//
// $.ui.invalidate('ui.render') redraws every render site of this plugin: the whole pane (its
// Buttons replaced, which can lose a press in flight), the band, every transcript row it
// labels. The Spinner's props can change many times while a turn runs, so a redraw per
// change keeps the pane redrawing for the whole turn. So a hook asks here first, and redraws
// only when the pane's last drawing showed what changed:
//   - a site's first call (or a new surface): when the pane shows the site's category, whose
//     list has the site's count
//   - new props or a new event input: when the pane shows that site's [詳細] card, at most
//     once per REDRAW_GAP_MS across all sites
// Anything else waits for the next drawing; [回数を更新] draws the pane again on request.
// The values view (values.js) needs no invalidate: it reads what it shows from $.state, so a
// write redraws it only while it is the drawing that read it.
//
// Pure: no $ here, so the hook files keep every $ call themselves. The pane's drawings write
// what they show into module variables, since $.state.set is refused while drawing.

import { siteOf } from './sites.js'

/** The shortest time between two redraws asked for because props changed. */
export const REDRAW_GAP_MS = 2000

// What the main pane showed at its last drawing: its view, and the site whose [詳細] card was
// open there. Both undefined while the pane is closed.
let shownView
let shownDetail
let lastPropsRedraw = -Infinity

/** Called by each drawing of the main pane: the view it drew, and the site it details. */
export function notePaneShows(view, detail) {
  shownView = view
  shownDetail = detail
}

/** Called when the main pane closes: nothing of it is on screen any more. */
export function notePaneClosed() {
  shownView = undefined
  shownDetail = undefined
}

/**
 * Whether the pane's last drawing was the view `view` (and the pane is still open). The values
 * view's timer runs only while it is.
 */
export function paneShowsView(view) {
  return shownView === view
}

/** Whether the pane's last drawing listed the site (its category's view). */
export function paneLists(id) {
  return shownView !== undefined && shownView === siteOf(id).category
}

/**
 * Whether a site's call should redraw the pane, and why: 'first' (a new site or surface the
 * pane lists), 'props' (new props in the open [詳細] card), or undefined for no redraw.
 * `now` is the time in milliseconds; a 'props' answer starts the next gap.
 */
export function redrawFor(id, { isNew = false, isChanged = false }, now) {
  if (!paneLists(id)) return undefined
  if (isNew) return 'first'
  if (!isChanged || shownDetail !== id) return undefined
  if (now - lastPropsRedraw < REDRAW_GAP_MS) return undefined
  lastPropsRedraw = now
  return 'props'
}

files.hooks/style.js:
// The look every view of this mod shares: spacing, column widths, colors, button roles, and
// small builders for the recurring blocks (a view's header, a section, a table row, a
// key/value field, a card). Pure: each builder takes the element table `$.ui.resolve(e)`
// handed out (`ui`) and never touches $, so the drawing files keep every $ call themselves.

/** Spacing, in character cells. */
export const SPACE = {
  page: 1, // the left and right padding of a whole view
  section: 1, // blank rows between a view's sections
  item: 1, // blank rows between multi-line items (the contents' categories)
  row: 0, // blank rows between the lines of a text-only field list
  control: 1, // blank rows between table rows that hold buttons, and between wrapped buttons
  inline: 1, // columns between buttons in a row
  mark: 2, // columns between a switch's mark and its button
  column: 2, // columns between the cells of a table row
  indent: 2, // the indent of a section's body under its heading
}

/** Fixed column widths, in character cells, so rows line up as a table. */
export const WIDTH = {
  label: 22, // a site's `[name]`: the longest is 22
  state: 11, // the on/off mark, its gap and its button
  count: 5, // `999 回`
  detail: 8, // the [詳細] button
  category: 14, // a category's name in the contents
  field: 20, // a field's name in a key/value list
  prop: 16, // a prop's name in the detail card
  value: 30, // a value's `[noun.method]` in the values view: `[classic.UserPromptExpansion]` is 29
}

/**
 * The palette: theme color names only, so the surface's theme decides the shade. Secondary
 * text is drawn with dimColor rather than a color of its own.
 */
export const COLOR = {
  on: 'success', // a switch that is on
  warn: 'warning', // something the surface does not draw
}

/**
 * Button roles, spread into a Button's props.
 * main: the one action a view leads to (show the samples), and the picked one of several
 *       choices (an open [詳細], the chosen way of drawing).
 * nav: moving between views, refreshing, closing, a switch that is on.
 * minor: an unpicked choice, a [詳細] not open, a switch that is off.
 * The run buttons of the APIs keep the surface's default look.
 */
export const BUTTON = {
  main: { variant: 'primary' },
  nav: { variant: 'secondary' },
  minor: { variant: 'secondary', dimColor: true },
}

/** The role of a button that is one of several choices: picked is main, the rest minor. */
export const choice = isPicked => (isPicked ? BUTTON.main : BUTTON.minor)

/** Dim text that wraps at the pane's edge. */
export const dim = (ui, key, text) => ui.Text({ key, dimColor: true, wrap: 'wrap', children: [text] })

/** A row of buttons (or other inline items), wrapping when the pane is narrow. */
export const inline = (ui, key, children, marginTop = 0, gap = SPACE.inline) =>
  ui.Box({
    key,
    marginTop,
    flexDirection: 'row',
    columnGap: gap,
    rowGap: SPACE.control,
    alignItems: 'center',
    flexWrap: 'wrap',
    children,
  })

/** A cell of fixed width; it never shrinks, so the next cell starts at the same column. */
export const cell = (ui, width, children, align = 'flex-start') =>
  ui.Box({ width, flexShrink: 0, flexDirection: 'row', justifyContent: align, children })

/**
 * The last cell of a row: takes the rest of the width. 'row' lays inline items out and wraps
 * them inside the cell; 'column' stacks lines of text that wrap at the cell's edge.
 */
export const fill = (ui, children, direction = 'row') =>
  ui.Box({
    flexGrow: 1,
    flexShrink: 1,
    flexDirection: direction,
    columnGap: SPACE.inline,
    rowGap: direction === 'row' ? SPACE.control : 0,
    alignItems: direction === 'row' ? 'center' : 'stretch',
    flexWrap: direction === 'row' ? 'wrap' : 'nowrap',
    children,
  })

/** A table row: fixed cells then a fill, on one line. */
export const tableRow = (ui, key, children, align = 'center') =>
  ui.Box({ key, flexDirection: 'row', columnGap: SPACE.column, alignItems: align, width: '100%', children })

/** A key/value line: the name dim in a fixed column, the value in normal text (or nodes). */
export const field = (ui, key, name, value, width = WIDTH.field) =>
  tableRow(
    ui,
    key,
    [
      cell(ui, width, [ui.Text({ dimColor: true, children: [name] })]),
      typeof value === 'string' ? fill(ui, [ui.Text({ wrap: 'wrap', children: [value] })], 'column') : fill(ui, value),
    ],
    'flex-start',
  )

/**
 * A view's header: the title, a one-line description, the navigation buttons in one row,
 * and an optional note under them.
 */
export const header = (ui, { title, about, nav, note }) =>
  ui.Box({
    key: 'header',
    flexDirection: 'column',
    width: '100%',
    children: [
      ui.Text({ bold: true, children: [title] }),
      about ? dim(ui, 'header-about', about) : null,
      nav && nav.length > 0 ? inline(ui, 'header-nav', nav, 1) : null,
      note ? ui.Box({ key: 'header-note', marginTop: 1, children: [dim(ui, 'header-note-text', note)] }) : null,
    ],
  })

/** A section: a bold heading, then its body indented under it. */
export const section = (ui, key, title, children, gap = SPACE.row) =>
  ui.Box({
    key,
    flexDirection: 'column',
    width: '100%',
    children: [
      ui.Text({ bold: true, children: [title] }),
      ui.Box({ flexDirection: 'column', rowGap: gap, paddingLeft: SPACE.indent, width: '100%', children }),
    ],
  })

/** A framed block: a dim rounded border with room inside. */
export const card = (ui, key, children) =>
  ui.Box({
    key,
    flexDirection: 'column',
    rowGap: SPACE.section,
    width: '100%',
    borderStyle: 'round',
    borderDimColor: true,
    paddingX: 2,
    paddingY: 1,
    children,
  })

/** A whole view: its sections one blank row apart, inside the page padding. */
export const page = (ui, children) =>
  ui.Box({ flexDirection: 'column', rowGap: SPACE.section, paddingX: SPACE.page, width: '100%', children })

/**
 * A table: its rows (each a row with whatever hangs under it, such as a result line) one
 * blank row apart, so the buttons of adjacent rows do not touch.
 */
export const table = (ui, key, rows) =>
  ui.Box({ key, flexDirection: 'column', rowGap: SPACE.control, width: '100%', children: rows })

/** The mark in front of a switch: a colored dot when on, a dim ring when off. */
export const stateMark = (ui, isOn) =>
  isOn ? ui.Text({ color: COLOR.on, children: ['●'] }) : ui.Text({ dimColor: true, children: ['○'] })

files.hooks/diag.js:
// [診断/press]: a short log of what reaches this mod around a press, for the pane to list.
// Kept in module variables, not $.state: a render hook may not write $.state, and a state
// write on every entry would redraw the pane, which is the very thing being watched. The pane
// shows the log as of its last drawing; [記録を更新] draws it again. A reload starts it over.
// Pure: no $ here, so the hook files keep every $ call themselves.

/** How many entries the log keeps; older ones fall off. */
const LIMIT = 100

const entries = []
let paneRenders = 0
let lastFocused // the main pane's e.props.isFocused at its last drawing

// The Spinner's redraws can recur all through a turn and would push the press and
// focus lines out of the log, so they are left out unless the diag section's switch keeps
// them. `noisePending`: the last redraw this mod asked for came from the Spinner, so the
// pane's next drawing is its echo.
let noiseKept = false
let noisePending = false

// `12:34:56.789`, local time
function stamp() {
  const now = new Date()
  const pad = (n, width = 2) => String(n).padStart(width, '0')
  return `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}.${pad(now.getMilliseconds(), 3)}`
}

/** Adds one line to the log: `kind` is a short tag (press, focus, render, invalidate). */
export function noteDiag(kind, text) {
  entries.push({ time: stamp(), kind, text })
  if (entries.length > LIMIT) entries.shift()
}

/** Whether the Spinner's redraw lines are kept in the log. Off until the switch turns it on. */
export function isNoiseKept() {
  return noiseKept
}

/** Flips the switch that keeps the Spinner's redraw lines in the log. */
export function toggleNoise() {
  noiseKept = !noiseKept
}

/**
 * Notes one $.ui.invalidate this mod makes. `isNoise` marks one the Spinner caused: left out
 * of the log unless the switch keeps it, along with the pane drawing it brings.
 */
export function noteInvalidate(text, isNoise = false) {
  noisePending = isNoise
  if (!isNoise || noiseKept) noteDiag('invalidate', text)
}

/**
 * Notes one drawing of the main pane: its running count and e.props.isFocused, with a mark
 * when the focus changed since the drawing before. A drawing that follows a Spinner's
 * redraw with the focus unchanged is noise.
 */
export function notePaneRender(e) {
  paneRenders += 1
  const isFocused = e.props.isFocused
  const isFocusChanged = lastFocused !== undefined && lastFocused !== isFocused
  const change = isFocusChanged ? `（${lastFocused} → ${isFocused}）` : ''
  lastFocused = isFocused
  const isNoise = noisePending && !isFocusChanged
  noisePending = false
  if (!isNoise || noiseKept) noteDiag('render', `Pane #${paneRenders} isFocused: ${isFocused}${change}`)
}

/** The log's lines, newest first. */
export function diagLines() {
  return entries.map(entry => `${entry.time} ${entry.kind}: ${entry.text}`).reverse()
}

/** Empties the log (the render count goes on). */
export function clearDiag() {
  entries.length = 0
}

files.hooks/press-guard.js:
// [press/再実行]: runs a pane's Button press again when it did not reach the Button's onPress.
//
// A Button's onPress stays in this mod's environment under a handle the host holds for the
// life of one drawing. A pane is drawn again whenever its props change, so a press that comes
// in just as the drawing it was aimed at is replaced (the first click on an unfocused pane
// focuses it, and `isFocused` changes) can find its handle gone and never reach the closure.
//
// So each guarded drawing keeps its own Buttons' closures here, by requestId and key, and wraps
// each onPress so that a run of it is seen. The ui.press hook (pane.js) opens a press record
// before next(e); if the chain settles, fails, or stays silent past a grace without the
// Button's onPress having started, the hook takes the press over and runs the closure the
// latest drawing holds under the same key. A press runs at most once: a closure the engine
// starts after the take-over finds the record taken and does nothing.
//
// Pure: no $ here, so the hook files keep every $ call themselves.

import { noteDiag } from './diag.js'

/** How long the hook waits for the press to reach an onPress before it takes it over. */
export const GRACE_MS = 2000

// The closures of the latest finished drawing, by requestId, then key
const drawn = new Map()
// The press in flight per `requestId key`: { started, takenOver }
const pending = new Map()

const slot = (requestId, key) => requestId + ' ' + key

/**
 * Starts one drawing of the pane `requestId`. `wrap(table)` hands back the element table with
 * its Button keeping each onPress here; `done(tree)` makes this drawing the latest and returns
 * the tree. A drawing that fails before done() leaves the previous one in place.
 */
export function guardDrawing(requestId) {
  const handlers = new Map()
  return {
    wrap(table) {
      const Button = props => {
        const onPress = props.onPress
        if (typeof onPress !== 'function') return table.Button(props)
        handlers.set(props.key, onPress)
        return table.Button({ ...props, onPress: press => runGuarded(requestId, props.key, onPress, press) })
      }
      return { ...table, Button }
    },
    done(tree) {
      drawn.set(requestId, handlers)
      return tree
    },
  }
}

// The onPress the surface runs: marks the press as reached, unless the hook already took it
// over, in which case it does nothing (the press has run once already)
function runGuarded(requestId, key, onPress, press) {
  const record = pending.get(slot(requestId, key))
  if (record?.takenOver) {
    noteDiag('[press/再実行]', `${key} の元の onPress が後から呼ばれたが、再実行済みなので何もしない`)
    return undefined
  }
  if (record) record.started = true
  return onPress(press)
}

/**
 * Opens the record of one press before next(e). Undefined when the latest drawing of that
 * pane has no guarded Button under the key (another site, or a key this mod does not keep):
 * such a press is only watched.
 */
export function beginPress(e) {
  if (!drawn.get(e.requestId)?.has(e.element)) return undefined
  const record = { started: false, takenOver: false }
  pending.set(slot(e.requestId, e.element), record)
  return record
}

/** Whether the press has reached (started) its Button's onPress. */
export function hasStarted(record) {
  return record.started
}

/**
 * Takes the press over and runs the latest drawing's closure for its key with `press` (the
 * ui.press argument). Marks the record first, so the engine's own onPress, if it still
 * comes, does nothing. Resolves to what the closure returned.
 */
export function takeOver(record, press, why) {
  record.takenOver = true
  const onPress = drawn.get(press.requestId)?.get(press.element)
  if (!onPress) {
    noteDiag('[press/再実行]', `${press.element}: ${why}。最新の描画にこのキーがないので再実行できない`)
    return undefined
  }
  noteDiag('[press/再実行]', `${press.element}: ${why}。最新の描画の onPress で実行する`)
  return onPress(press)
}

/**
 * Closes the record of a press the engine ran itself. A taken-over record stays until the
 * next press on the key replaces it, so the engine's own onPress, arriving late, still finds it.
 */
export function endPress(press, record) {
  const key = slot(press.requestId, press.element)
  if (!record.takenOver && pending.get(key) === record) pending.delete(key)
}

files.hooks/bytes.js:
// Pure builders of the bytes the media samples hand to the engine: the cells of [Pane/Raster],
// the pixels of [Pane/Image], and the short beep [$.audio.play] plays. Each answers base64,
// built with btoa over a binary string (a global of the hooks environment).
//
// Pure: no $ here, so the hook files keep every $ call themselves.

/** The size of [Pane/Raster], in cells. */
export const RASTER = { columns: 24, rows: 6 }

/** The size of [Pane/Image]: its pixels, and the cells it is drawn over. */
export const IMAGE = { width: 8, height: 4, columns: 8, rows: 2 }

// Bytes to base64
function toBase64(bytes) {
  let binary = ''
  for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i])
  return btoa(binary)
}

// A hue (0 to 1, wrapping) at a value (0 to 1), saturation fixed, as [r, g, b] 0 to 255
function hsv(hue, value) {
  const h = (((hue % 1) + 1) % 1) * 6
  const s = 0.6
  const c = value * s
  const x = c * (1 - Math.abs((h % 2) - 1))
  const m = value - c
  const [r, g, b] = h < 1 ? [c, x, 0] : h < 2 ? [x, c, 0] : h < 3 ? [0, c, x] : h < 4 ? [0, x, c] : h < 5 ? [x, 0, c] : [c, 0, x]
  return [r, g, b].map(part => Math.round((part + m) * 255))
}

// The color of one grid position: the hue runs across, the value falls down, `phase` shifts it
function shade(x, y, width, height, phase) {
  return hsv(x / width + phase, 0.95 - (0.5 * y) / Math.max(1, height - 1))
}

/**
 * The cells of a `columns` x `rows` Raster (RasterProps `cells`): row-major, each cell three
 * little-endian u32 [codePoint, foreground, background]. Each cell is an upper half block, so
 * one cell shows two rows of the gradient (its foreground above, its background below).
 */
export function rasterCells(columns, rows, phase) {
  const view = new DataView(new ArrayBuffer(columns * rows * 12))
  for (let y = 0; y < rows; y += 1) {
    for (let x = 0; x < columns; x += 1) {
      const at = (y * columns + x) * 12
      const [fr, fg, fb] = shade(x, y * 2, columns, rows * 2, phase)
      const [br, bg, bb] = shade(x, y * 2 + 1, columns, rows * 2, phase)
      view.setUint32(at, 0x2580, true)
      view.setUint32(at + 4, (fr << 16) | (fg << 8) | fb, true)
      view.setUint32(at + 8, (br << 16) | (bg << 8) | bb, true)
    }
  }
  return toBase64(new Uint8Array(view.buffer))
}

/** An Image source (ImageSource `{ rgba, width, height }`): the same gradient, opaque. */
export function imageSource(width, height, phase) {
  const bytes = new Uint8Array(width * height * 4)
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const at = (y * width + x) * 4
      const [r, g, b] = shade(x, y, width, height, phase)
      bytes[at] = r
      bytes[at + 1] = g
      bytes[at + 2] = b
      bytes[at + 3] = 255
    }
  }
  return { rgba: toBase64(bytes), width, height }
}

/**
 * A short, quiet beep as a WAV file (AudioClip `{ base64, mime }`): 8-bit mono at 8 kHz, a
 * 660 Hz tone of `ms` milliseconds at a low level, faded in and out so it does not click.
 */
export function beepWav(ms = 200) {
  const rate = 8000
  const count = Math.round((rate * ms) / 1000)
  const fade = Math.round(rate * 0.01)
  const view = new DataView(new ArrayBuffer(44 + count))
  const text = (at, word) => {
    for (let i = 0; i < word.length; i += 1) view.setUint8(at + i, word.charCodeAt(i))
  }
  text(0, 'RIFF')
  view.setUint32(4, 36 + count, true)
  text(8, 'WAVE')
  text(12, 'fmt ')
  view.setUint32(16, 16, true) // the fmt chunk's size
  view.setUint16(20, 1, true) // PCM
  view.setUint16(22, 1, true) // mono
  view.setUint32(24, rate, true) // samples per second
  view.setUint32(28, rate, true) // bytes per second
  view.setUint16(32, 1, true) // bytes per sample
  view.setUint16(34, 8, true) // bits per sample
  text(36, 'data')
  view.setUint32(40, count, true)
  for (let i = 0; i < count; i += 1) {
    const envelope = Math.min(1, i / fade, (count - 1 - i) / fade)
    view.setUint8(44 + i, Math.round(128 + 40 * envelope * Math.sin((2 * Math.PI * 660 * i) / rate)))
  }
  return { base64: toBase64(new Uint8Array(view.buffer)), mime: 'audio/wav' }
}

